import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Referencia de configuración","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/index.md","filePath":"es-ES/user-guide/settings/index.md","lastUpdated":1787982919000}'),i={name:"es-ES/user-guide/settings/index.md"};function r(o,e,d,l,c,u){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="referencia-de-configuracion" tabindex="-1">Referencia de configuración <a class="header-anchor" href="#referencia-de-configuracion" aria-label="Permalink to &quot;Referencia de configuración&quot;">​</a></h1><p>Lertaro ofrece un conjunto exhaustivo y granular de opciones de personalización. Tanto si deseas ajustar las dimensiones en píxeles de la barra de búsqueda como personalizar atajos globales, modificar la frecuencia de indexación o gestionar plugins y espacios de trabajo, todo se configura desde el Centro de Configuración.</p><h2 id="_1-caracteristicas-de-la-ventana-e-interaccion" tabindex="-1">1. Características de la ventana e interacción <a class="header-anchor" href="#_1-caracteristicas-de-la-ventana-e-interaccion" aria-label="Permalink to &quot;1. Características de la ventana e interacción&quot;">​</a></h2><ul><li><strong>Ventana redimensionable y maximizable</strong>: La ventana de Configuración permite ajustar libremente sus bordes, maximizar con doble clic en la barra de título y recuerda sus dimensiones automáticamente.</li><li><strong>Búsqueda global en Configuración</strong>: En la esquina superior derecha de la barra de título se incluye un buscador dedicado. Utiliza el motor de coincidencia difusa fzf de Lertaro para buscar entre todas las secciones, incluidos los ajustes de plugins y acciones. Al pulsar Intro, salta directamente a la opción y la resalta con un borde parpadeante.</li><li><strong>Barras de pestañas desplazables</strong>: En las secciones con varias subpestañas (como General, Atajos, Indexación), aparecen flechas de navegación a ambos lados para garantizar que todas las pestañas permanezcan visibles en cualquier idioma.</li></ul><h2 id="_2-resumen-de-secciones-de-configuracion" tabindex="-1">2. Resumen de secciones de configuración <a class="header-anchor" href="#_2-resumen-de-secciones-de-configuracion" aria-label="Permalink to &quot;2. Resumen de secciones de configuración&quot;">​</a></h2><p>La barra lateral izquierda contiene las siguientes diez secciones principales:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Sección</th><th style="text-align:left;">Contenido principal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./service-status.html">Estado del servicio</a></strong></td><td style="text-align:left;">Estado del servicio de Windows en segundo plano, diagnóstico y visor de registros en vivo para Service, App y Hook.</td></tr><tr><td style="text-align:left;"><strong><a href="./index-drives.html">Gestión de indexación</a></strong></td><td style="text-align:left;">Unidades locales (NTFS / ReFS / FAT32), unidades de red (SMB / NAS), distribuciones WSL, carpetas personalizadas y reglas de exclusión.</td></tr><tr><td style="text-align:left;"><strong><a href="./general.html">Configuración general</a></strong></td><td style="text-align:left;">Inicio automático, aceleración por hardware, servicio compatible con IPC, dimensiones de la barra de búsqueda y opciones de vista previa.</td></tr><tr><td style="text-align:left;"><strong><a href="./hotkeys-page.html">Atajos de teclado</a></strong></td><td style="text-align:left;">Atajos de búsqueda global, teclas de navegación, accesos de plugins, lista negra de procesos y omisión en pantalla completa.</td></tr><tr><td style="text-align:left;"><strong><a href="./plugins.html">Plugins</a></strong></td><td style="text-align:left;">Lista de plugins instalados, activación por componentes, formularios de configuración y ecosistema de Flow Launcher.</td></tr><tr><td style="text-align:left;"><strong><a href="./localsend.html">LocalSend</a></strong></td><td style="text-align:left;">Configuración del protocolo de transferencia inalámbrica compatible con LocalSend (nombre de dispositivo, puerto, PIN y autoguardado).</td></tr><tr><td style="text-align:left;"><strong><a href="./favorites.html">Favoritos</a></strong></td><td style="text-align:left;">Accesos directos con estrella a carpetas, archivos y URLs con ordenación por arrastre y búsqueda rápida por alias.</td></tr><tr><td style="text-align:left;"><strong><a href="./history.html">Historial</a></strong></td><td style="text-align:left;">Gestión de resultados abiertos y términos de búsqueda consultados, reapertura inteligente y limpieza.</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-launch.html">Inicio rápido</a></strong></td><td style="text-align:left;">Gestiona accesos directos manuales y elige las fuentes de datos dinámicas que aparecen cuando la ventana de búsqueda rápida está vacía.</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-panel.html">Panel rápido</a></strong></td><td style="text-align:left;">Espacios de trabajo flotantes acoplados, agregación de carpetas de múltiples orígenes, recepción de archivos y pestañas de plugins.</td></tr><tr><td style="text-align:left;"><strong><a href="./appearance.html">Apariencia y temas</a></strong></td><td style="text-align:left;">Selector de modo Claro / Oscuro / Seguir al sistema y tarjetas con vista previa en miniatura de temas integrados y seleccionados.</td></tr><tr><td style="text-align:left;"><strong><a href="./about.html">Acerca de y actualizaciones</a></strong></td><td style="text-align:left;">Versiones de componentes, rutas a directorios de datos de usuario y equipo, rotación de copias de seguridad y actualización silenciosa.</td></tr></tbody></table><p>Los siguientes capítulos describen en detalle cada opción, rango de parámetros y comportamiento predeterminado de cada sección.</p>',8)])])}const f=a(i,[["render",r]]);export{p as __pageData,f as default};
